import { once } from 'node:events';
import { SearchDb } from '../../dist/src/search/db.js';
import { join } from 'node:path';
import { writeIndex } from '../../dist/src/search/cache.js';
import {
  acquireSearchLock,
  acquireSearchAccess,
} from '../../dist/src/search/lock.js';

const [dir, mode, timeout] = process.argv.slice(2);
process.send('started');
try {
  if (mode === 'shared' || mode === 'exclusive') {
    const release = await acquireSearchAccess(dir, mode, Number(timeout));
    try {
      process.send('acquired');
      await once(process, 'message');
    } finally {
      await release();
    }
  } else if (mode === 'fts-reader') {
    const db = new SearchDb(join(dir, 'search.db'), true);
    const query = () =>
      db.execute(
        "SELECT id,fts_score(body,heading,path,'alpha') AS score FROM lexical_chunks ORDER BY score DESC LIMIT 5",
      );
    try {
      process.send({ rows: (await query()).rows });
      process.send('acquired');
      await once(process, 'message');
      process.send({ finalRows: (await query()).rows });
    } finally {
      await db.close();
    }
  } else if (mode === 'reader') {
    const db = new SearchDb(join(dir, 'search.db'), true);
    try {
      await db.execute('SELECT * FROM crash_test');
      process.send('acquired');
      await once(process, 'message');
    } finally {
      await db.close();
    }
  } else if (mode === 'lock') {
    const release = await acquireSearchLock(dir, Number(timeout));
    process.send('acquired');
    await once(process, 'message');
    await release();
  } else {
    await writeIndex(dir, dir, true, async (db) => {
      await db.execute('CREATE TABLE crash_test (value TEXT)');
      await db.execute("INSERT INTO crash_test VALUES ('replacement')");
      process.send('acquired');
      await once(process, 'message');
    });
  }
  process.send('done');
  process.disconnect();
} catch (error) {
  process.send({ error: error.message });
  process.disconnect();
  process.exitCode = 1;
}

import {
  closeDb,
  ensureMeta,
  openDb,
  setStoredModel,
} from '../../dist/src/search/db.js';

const [latDir, model] = process.argv.slice(2);
if (!latDir || !model) {
  throw new Error('usage: seed-model.mjs <lat-dir> <model>');
}

const db = openDb(latDir);
try {
  await ensureMeta(db);
  await setStoredModel(db, model);
  await db.checkpoint();
} finally {
  await closeDb(db);
}

import { SearchDb } from '../../dist/src/search/db.js';
const db = new SearchDb(process.argv[2], true);
const query =
  "SELECT body,fts_score(body,heading,path,'needl') AS score FROM lexical_chunks ORDER BY score DESC LIMIT 5";
try {
  await db.execute(query);
  process.send('ready');
  process.once('message', async () => {
    try {
      process.send((await db.execute(query)).rows);
      await db.close();
      process.send('closed');
      process.once('message', () => process.exit(0));
    } catch (error) {
      console.error(error);
      process.exit(1);
    }
  });
} catch (error) {
  console.error(error);
  process.exit(1);
}

import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import {
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  rmSync,
  readFileSync,
  readdirSync,
  symlinkSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { createServer } from 'node:https';
import { delimiter, dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { after, test } from 'node:test';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const scratch = mkdtempSync(join(tmpdir(), 'lat-action-test-'));
const artifact = join(scratch, 'action');
cpSync(join(root, '.lat-build/check-action'), artifact, { recursive: true });
// Model npm's install boundary without requiring a published core or network.
// The checker and dependency tree are the real isolated build under test.
const npmBin = join(scratch, 'npm-bin');
mkdirSync(join(npmBin, 'node_modules/npm/bin'), { recursive: true });
writeFileSync(
  join(npmBin, process.platform === 'win32' ? 'npm.cmd' : 'npm'),
  '',
);
const installLog = join(scratch, 'install.json');
writeFileSync(
  join(npmBin, 'node_modules/npm/bin/npm-cli.js'),
  `
const { mkdirSync, symlinkSync, writeFileSync } = require('node:fs');
const { join } = require('node:path');
writeFileSync(${JSON.stringify(installLog)}, JSON.stringify(process.argv.slice(2)));
if (process.env.TEST_INSTALL_FAIL) process.exit(42);
const target = process.argv[process.argv.indexOf('--prefix') + 1];
mkdirSync(join(target, 'node_modules/@lat.md'), { recursive: true });
symlinkSync(${JSON.stringify(join(artifact, 'runtime'))}, join(target, 'node_modules/@lat.md/core'), process.platform === 'win32' ? 'junction' : 'dir');
`,
);
const testPath = npmBin + delimiter + process.env.PATH;
const workspace = join(scratch, 'workspace');
const project = join(workspace, 'project with spaces');
mkdirSync(join(project, 'lat.md'), { recursive: true });
after(() =>
  rmSync(scratch, {
    recursive: true,
    force: true,
    maxRetries: 10,
    retryDelay: 100,
  }),
);
function action(extra = {}) {
  return spawnSync(process.execPath, [join(artifact, 'action/index.js')], {
    cwd: scratch,
    encoding: 'utf8',
    env: {
      ...process.env,
      NODE_PATH: '',
      PATH: testPath,
      INPUT_VERSION: 'latest',
      XDG_CACHE_HOME: join(scratch, 'user-cache'),
      GITHUB_WORKSPACE: workspace,
      'INPUT_WORKING-DIRECTORY': 'project with spaces',
      INPUT_PROFILE: 'false',
      ...extra,
    },
  });
}
// @lat: [[tests/distribution-tests#Action installs selected core]]
test('action installs latest or an explicit version outside the project', () => {
  writeFileSync(
    join(project, 'lat.md/lat.md'),
    '# Project\n\nWorking documentation.\n',
  );
  const result = action({ INPUT_PROFILE: 'true' });
  assert.equal(result.status, 0, result.stdout + result.stderr);
  assert.match(result.stdout, /Lat core/);
  let args = JSON.parse(readFileSync(installLog, 'utf8'));
  assert.equal(args.at(-1), '@lat.md/core@latest');
  assert.ok(args.includes('--ignore-scripts'));
  assert.ok(args.includes('--prefer-online'));
  assert.equal(existsSync(args[args.indexOf('--prefix') + 1]), false);
  const pinned = action({ INPUT_VERSION: '0.1.0' });
  assert.equal(pinned.status, 0, pinned.stdout + pinned.stderr);
  args = JSON.parse(readFileSync(installLog, 'utf8'));
  assert.equal(args.at(-1), '@lat.md/core@0.1.0');
  const failed = action({ TEST_INSTALL_FAIL: '1' });
  assert.equal(failed.status, 1);
  assert.match(failed.stderr, /Core installation failed/);
  const failedArgs = JSON.parse(readFileSync(installLog, 'utf8'));
  assert.equal(
    existsSync(failedArgs[failedArgs.indexOf('--prefix') + 1]),
    false,
  );
  assert.doesNotMatch(failed.stdout, /Lat core/);
  for (const version of [
    'file:../core',
    'npm:other',
    '1.0.0; echo bad',
    '--help',
  ]) {
    rmSync(installLog);
    assert.equal(action({ INPUT_VERSION: version }).status, 1);
    assert.equal(existsSync(installLog), false);
    writeFileSync(installLog, '[]');
  }
  assert.match(result.stdout, /All checks passed/);
  assert.equal(existsSync(join(workspace, 'node_modules')), false);
  const runtime = join(artifact, 'runtime');
  assert.equal(existsSync(join(runtime, 'node_modules/@lat.md/embed')), false);
  // Exercise binary assets and dynamic worker/module paths in the isolated core runtime.
  const probe = join(scratch, 'probe.mjs');
  writeFileSync(
    probe,
    `
import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
const base = ${JSON.stringify(pathToFileURL(join(runtime, 'dist') + '/').href)};
const { analyzeMarkdownProject } = await import(new URL('project-analysis.js', base));
const { SOURCE_FILE_EXTENSIONS } = await import(new URL('source-formats.js', base));
const { resolveSourceSymbol } = await import(new URL('source-parser.js', base));
const { analyzeExternalDocument } = await import(new URL('external-documents.js', base));
const dir = ${JSON.stringify(project)};
await analyzeMarkdownProject(join(dir, 'lat.md'), dir, { executor: 'workers', cache: false });
for (const extension of SOURCE_FILE_EXTENSIONS) {
  writeFileSync(join(dir, 'empty' + extension), '');
  const parsed = await resolveSourceSymbol('empty' + extension, 'missing', dir);
  assert.equal(parsed.error, undefined, extension);
}
for (const [name, text] of [['guide.rst', 'Title\\n=====\\n\\nBody.\\n'], ['guide.adoc', '= Title\\n\\nBody.\\n']]) {
  const result = await analyzeExternalDocument(name, text);
  assert.ok(result.sections.length > 0);
}
`,
  );
  const assets = spawnSync(process.execPath, [probe], {
    cwd: scratch,
    encoding: 'utf8',
  });
  assert.equal(assets.status, 0, assets.stdout + assets.stderr);
});
// @lat: [[tests/distribution-tests#Action preserves validation failures]]
test('action fails the job for broken links and invalid inputs', () => {
  writeFileSync(
    join(project, 'lat.md/lat.md'),
    '# Project\n\nBroken [[Missing]].\n',
  );
  const result = action();
  assert.equal(result.status, 1);
  assert.match(result.stdout + result.stderr, /Missing/);
  assert.equal(action({ INPUT_PROFILE: 'invalid' }).status, 1);
  assert.equal(
    action({ 'INPUT_WORKING-DIRECTORY': 'missing directory' }).status,
    1,
  );
});

// @lat: [[tests/distribution-tests#Action rejects cache symlinks]]
test('action rejects cache symlinks without changing outside files', () => {
  for (const [index, link] of [
    'lat.md',
    'lat.md/.cache',
    'lat.md/.cache/external',
    'lat.md/.cache/external/unused',
    'lat.md/.cache/external/unused.json',
    'lat.md/.cache/external/unused.json.lock',
    'lat.md/.cache/parsed',
    'lat.md/.cache/parsed/la',
  ].entries()) {
    const checkout = join(workspace, `symlink-${index}`);
    const victim = join(scratch, `victim-${index}`);
    mkdirSync(join(victim, 'unused'), { recursive: true });
    writeFileSync(join(victim, 'unused.json'), 'victim metadata');
    writeFileSync(join(victim, 'unused/keep.txt'), 'victim content');
    writeFileSync(
      join(victim, 'lat.md'),
      '# Project\n\nValid documentation.\n',
    );
    const linkPath = join(checkout, link);
    mkdirSync(dirname(linkPath), { recursive: true });
    symlinkSync(
      victim,
      linkPath,
      process.platform === 'win32' ? 'junction' : 'dir',
    );
    if (link !== 'lat.md') {
      writeFileSync(
        join(checkout, 'lat.md/lat.md'),
        '# Project\n\nValid documentation.\n',
      );
    }
    if (
      link.startsWith('lat.md/.cache/external/') &&
      !link.endsWith('/unused.json')
    ) {
      writeFileSync(join(checkout, 'lat.md/.cache/external/unused.json'), '{}');
    }
    const before = readdirSync(victim, { recursive: true }).sort();
    const result = action({ 'INPUT_WORKING-DIRECTORY': `symlink-${index}` });
    assert.equal(result.status, 1, link + result.stdout + result.stderr);
    assert.match(
      result.stdout + result.stderr,
      /unsafe cache path.*symbolic link/,
    );
    assert.deepEqual(
      readdirSync(victim, { recursive: true }).sort(),
      before,
      link,
    );
    assert.equal(
      readFileSync(join(victim, 'unused.json'), 'utf8'),
      'victim metadata',
    );
    assert.equal(
      readFileSync(join(victim, 'unused/keep.txt'), 'utf8'),
      'victim content',
    );
  }
});

// @lat: [[tests/distribution-tests#Action ignores planted Git caches]]
test('action never opens Git configuration planted in the checkout', async () => {
  const server = createServer(
    {
      cert: readFileSync(
        join(root, 'tests/external-sources/fixtures/localhost-cert.pem'),
      ),
      key: readFileSync(
        join(root, 'tests/external-sources/fixtures/localhost-key.pem'),
      ),
    },
    (_request, response) => {
      response.writeHead(401, { 'www-authenticate': 'Basic realm="test"' });
      response.end('Authentication required');
    },
  );
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  try {
    const checkout = join(workspace, 'planted-git');
    const cache = join(checkout, 'lat.md/.cache/external/upstream');
    const marker = join(scratch, 'credential-helper-ran');
    const commit = 'a'.repeat(40);
    const repo = `https://localhost:${server.address().port}/repo.git`;
    mkdirSync(dirname(cache), { recursive: true });
    const git = (...args) => {
      const result = spawnSync('git', args, { encoding: 'utf8' });
      assert.equal(result.status, 0, result.stderr);
    };
    git('init', '--bare', '--template=', cache);
    git('-C', cache, 'remote', 'add', 'origin', repo);
    git('-C', cache, 'config', 'remote.origin.promisor', 'true');
    git('-C', cache, 'config', 'remote.origin.partialclonefilter', 'blob:none');
    git(
      '-C',
      cache,
      'config',
      'credential.helper',
      `!echo compromised > "${marker.replaceAll('\\', '/')}"`,
    );
    writeFileSync(
      cache + '.json',
      JSON.stringify({ ver: 1, source: repo, commit, strategy: 'checkout' }),
    );
    writeFileSync(
      join(checkout, 'lat.md/lat.md'),
      `---\nlat:\n  external-sources:\n    upstream:\n      repo: ${repo}\n      commit: ${commit}\n      strategy: checkout\n---\n# Project\n\nRead [[upstream:guide.md]].\n`,
    );
    const run = (command, args, env) =>
      new Promise((resolve, reject) => {
        const child = spawn(command, args, {
          cwd: scratch,
          env: { ...process.env, ...env },
        });
        let output = '';
        child.stdout.on('data', (data) => {
          output += data;
        });
        child.stderr.on('data', (data) => {
          output += data;
        });
        child.on('error', reject);
        child.on('close', (status) => resolve({ status, output }));
      });
    const env = {
      GIT_SSL_CAINFO: join(
        root,
        'tests/external-sources/fixtures/localhost-cert.pem',
      ),
      GIT_TERMINAL_PROMPT: '0',
      GIT_CONFIG_NOSYSTEM: '1',
      GIT_CONFIG_GLOBAL: process.platform === 'win32' ? 'NUL' : '/dev/null',
    };
    // Prove this fixture really executes its helper if a checker trusts the cache.
    await run('git', ['-C', cache, 'show', `${commit}:guide.md`], env);
    assert.equal(
      existsSync(marker),
      true,
      'malicious fixture did not execute its helper',
    );
    rmSync(marker);
    const result = await run(
      process.execPath,
      [join(artifact, 'action/index.js')],
      {
        ...env,
        PATH: testPath,
        INPUT_VERSION: 'latest',
        XDG_CACHE_HOME: join(scratch, 'user-cache'),
        GITHUB_WORKSPACE: workspace,
        'INPUT_WORKING-DIRECTORY': 'planted-git',
        INPUT_PROFILE: 'false',
      },
    );
    assert.equal(result.status, 1, result.output);
    assert.equal(existsSync(marker), false, result.output);
    assert.match(
      result.output,
      /Authentication failed|could not read Username/,
    );
    assert.equal(
      existsSync(cache),
      false,
      'legacy cache should be removed without invoking Git',
    );
    const alias = join(scratch, 'cache-home-alias');
    symlinkSync(
      checkout,
      alias,
      process.platform === 'win32' ? 'junction' : 'dir',
    );
    for (const cacheHome of [checkout, alias]) {
      const unsafeRoot = action({
        'INPUT_WORKING-DIRECTORY': 'planted-git',
        XDG_CACHE_HOME: cacheHome,
      });
      assert.equal(unsafeRoot.status, 1, unsafeRoot.stdout + unsafeRoot.stderr);
      assert.match(
        unsafeRoot.stdout + unsafeRoot.stderr,
        /managed Git cache must be outside the project/,
      );
      assert.equal(existsSync(marker), false);
    }
  } finally {
    await new Promise((resolve, reject) =>
      server.close((error) => (error ? reject(error) : resolve())),
    );
  }
});

import { afterEach, expect, it } from 'vitest';
import { mkdtemp, mkdir, writeFile, rm, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { request, type IncomingMessage } from 'node:http';
import { plainStyler } from '@lat.md/core/context';
import { startViewServer, type ViewServer } from '../src/view/server.js';
import { trustedLiveRequest } from '../src/view/request-security.js';

let root: string | undefined;
let server: ViewServer | undefined;
afterEach(async () => {
  await server?.close();
  server = undefined;
  if (root) await rm(root, { recursive: true, force: true });
  root = undefined;
});

function get(
  url: string,
  headers: Record<string, string> = {},
  method = 'GET',
) {
  return new Promise<{
    status: number;
    headers: IncomingMessage['headers'];
    body: string;
  }>((resolve, reject) => {
    const req = request(url, { headers, method }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () =>
        resolve({ status: res.statusCode!, headers: res.headers, body }),
      );
    });
    req.on('error', reject);
    req.end();
  });
}

// @lat: [[view/specs#Live request and resource isolation]]
it('rejects rebinding and cross-origin requests while isolating active resource documents', async () => {
  root = await mkdtemp(join(tmpdir(), 'lat-live-security-'));
  const latDir = join(root, 'lat.md');
  await mkdir(latDir);
  const document = '# Project\n\nOriginal content.\n';
  await writeFile(join(latDir, 'lat.md'), document);
  await writeFile(
    join(latDir, 'attack.html'),
    '<script src="/resources/attack.js"></script>',
  );
  await writeFile(
    join(latDir, 'attack.js'),
    'fetch("/api/document", {method:"PATCH"})',
  );
  await writeFile(
    join(latDir, 'image.svg'),
    '<svg xmlns="http://www.w3.org/2000/svg" onload="alert(1)"/>',
  );
  server = await startViewServer(
    { projectRoot: root, latDir, mode: 'cli', styler: plainStyler },
    { port: 0, watch: false, git: false },
  );
  const authority = new URL(server.url).host;
  expect((await get(server.url + 'api/index')).status).toBe(200);
  expect(
    (
      await get(server.url + 'api/index', {
        Host: `evil.example:${new URL(server.url).port}`,
      })
    ).status,
  ).toBe(403);
  expect(
    (await get(server.url + 'api/index', { Host: 'localhost:1' })).status,
  ).toBe(403);
  expect(
    (
      await get(server.url + 'api/index', {
        Host: `localhost:${new URL(server.url).port}`,
      })
    ).status,
  ).toBe(200);
  for (const Origin of ['https://evil.example', 'null', 'http://localhost:1'])
    expect(
      (await get(server.url + 'api/document', { Origin }, 'PATCH')).status,
    ).toBe(403);
  const sameOrigin = await get(
    server.url + 'api/document',
    { Origin: `http://${authority}` },
    'PATCH',
  );
  expect(sameOrigin.status).not.toBe(403); // Reaches normal body validation.
  expect(await readFile(join(latDir, 'lat.md'), 'utf8')).toBe(document);
  for (const file of ['attack.html', 'attack.js', 'image.svg']) {
    const result = await get(server.url + 'resources/' + file);
    expect(result.status).toBe(200);
    expect(result.headers['content-security-policy']).toContain(
      "sandbox; default-src 'none'",
    );
    expect(result.headers['content-security-policy']).not.toContain(
      'allow-scripts',
    );
    expect(result.headers['x-content-type-options']).toBe('nosniff');
    if (file === 'image.svg')
      expect(result.headers['content-disposition']).toBeUndefined();
    else expect(result.headers['content-disposition']).toBe('attachment');
  }
});

it('allows explicitly configured and IPv6 listener authorities without trusting forwarding headers', () => {
  const req = (host: string) =>
    ({
      headers: { host },
      socket: { localPort: 4242 },
      method: 'GET',
      url: '/',
    }) as IncomingMessage;
  expect(trustedLiveRequest(req('[::1]:4242'), '::1')).toBe(true);
  expect(trustedLiveRequest(req('docs.example:4242'), 'docs.example')).toBe(
    true,
  );
  expect(trustedLiveRequest(req('evil.example:4242'), 'docs.example')).toBe(
    false,
  );
  expect(
    trustedLiveRequest(
      {
        ...req('evil.example:4242'),
        headers: {
          host: 'evil.example:4242',
          'x-forwarded-host': 'localhost:4242',
        },
      } as unknown as IncomingMessage,
      '127.0.0.1',
    ),
  ).toBe(false);
});

import { afterEach, expect, it } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtemp, mkdir, writeFile, symlink, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { scanCodeRefs } from '@lat.md/core/code-refs';
import { getSection } from '@lat.md/core/cli/section';
import { plainStyler } from '@lat.md/core/context';
import { resolveSourceSymbol } from '@lat.md/core/source-parser';
import { analyzeMarkdownFile } from '@lat.md/core/markdown-analysis';

const roots: string[] = [];
afterEach(async () => {
  await Promise.all(
    roots.splice(0).map((root) => rm(root, { recursive: true, force: true })),
  );
});
async function fixture() {
  const parent = await mkdtemp(join(tmpdir(), 'lat-reference-security-'));
  roots.push(parent);
  const root = join(parent, 'project');
  const latDir = join(root, 'lat.md');
  await mkdir(latDir, { recursive: true });
  return { parent, root, latDir };
}

// @lat: [[tests/section#Source reads stay inside the project]]
it('rejects parent traversal and symlinks before resolving or rendering source snippets', async () => {
  const { parent, root, latDir } = await fixture();
  await writeFile(
    join(parent, 'private.ts'),
    'export const token = "[REDACTED]";',
  );
  await symlink(join(parent, 'private.ts'), join(root, 'linked.ts'));
  await writeFile(join(root, 'safe.ts'), 'export const token = "public";');
  await writeFile(
    join(latDir, 'lat.md'),
    '# Project\n\nSee [[../private.ts#token]], [[linked.ts#token]], and [[safe.ts#token]].\n',
  );
  for (const path of ['../private.ts', 'linked.ts'])
    expect((await resolveSourceSymbol(path, 'token', root)).found).toBe(false);
  const section = await getSection(
    { projectRoot: root, latDir, styler: plainStyler, mode: 'cli' },
    'Project',
  );
  expect(JSON.stringify(section)).not.toContain('outside-secret');
  expect(section.kind).toBe('found');
  if (section.kind === 'found')
    expect(section.outgoingSourceRefs.map((ref) => ref.file)).toEqual([
      'safe.ts',
    ]);
});

// @lat: [[tests/check-code-refs#Unambiguous reference filenames]]
it.skipIf(process.platform === 'win32')(
  'keeps colon and newline filenames identical in rg and fallback scans',
  async () => {
    const { root, latDir } = await fixture();
    await writeFile(join(latDir, 'lat.md'), '# Project\n\nDocumentation.\n');
    await writeFile(join(root, '.env'), 'PRIVATE_BACKLINK');
    const names = ['.env:1:backlink.ts', 'line\nbreak.ts'];
    for (const name of names)
      await writeFile(
        join(root, name),
        `// @${'lat'}: [[lat.md/lat#Project]]\n`,
      );
    execFileSync('git', ['init', '-q', root]);
