              ).startsWith('CREATE INDEX IF NOT EXISTS chunks_fts')
            )
              throw new Error('repair failed');
            return run(statement);
          });
        await expect(indexSections(f.lat, f.db, engine)).rejects.toThrow(
          'repair failed',
        );
        failure.mockRestore();
        expect(await scores()).toEqual(drifted);
        expect(
          (
