        expect(engine.embed).not.toHaveBeenCalled();
        const execute = vi.spyOn(f.db, 'execute');
        await indexSections(f.lat, f.db, engine);
        expect(
          execute.mock.calls.some(([s]) =>
            /DROP INDEX|CREATE INDEX/.test(typeof s === 'string' ? s : s.sql),
          ),
        ).toBe(false);
      } finally {
        await f.db.close();
      }
    },
  );

