        "INSERT INTO embeddings VALUES ('shared',vector32('[0,1]'))",
      );
      await f.db.execute('BEGIN');
      for (let i = 0; i < 51; i++)
        await f.db.execute({
          sql: 'INSERT INTO sections VALUES (?,?,?,?,?,?,?,?)',
          args: [
            `owner${String(i).padStart(2, '0')}`,
            'guide',
            `Owner ${i}`,
            'intro',
            'hash',
            null,
            1,
            1,
          ],
        });
      for (let i = 0; i < 210; i++)
        await f.db.execute({
          sql: 'INSERT INTO chunks VALUES (?,?,?,?,?,?,?,?,?,?)',
          args: [
            i + 1,
            `chunk${i}`,
            `owner${String(i < 160 ? 0 : i - 159).padStart(2, '0')}`,
            i,
            'paragraph',
            '[]',
            'ordinary text',
            'Heading',
            'Path',
            'shared',
          ],
        });
      await f.db.execute('COMMIT');
      await ensureSectionsSchema(f.db, 2);
      const hits = await searchSections(f.db, 'zeta', simple, 5);
      expect(hits.some((r) => r.id === 'owner01')).toBe(true);
      expect(hits[0].diagnostics.semanticCandidates).toBe(210);
      expect(hits[0].diagnostics.semanticCapped).toBe(false);
      await f.db.execute('DROP INDEX chunks_fts');
      await f.db.execute("UPDATE chunks SET section_id='owner00'");
      await f.db.execute('BEGIN');
      for (let i = 210; i < 600; i++)
        await f.db.execute({
          sql: 'INSERT INTO chunks VALUES (?,?,?,?,?,?,?,?,?,?)',
          args: [
            i + 1,
            `chunk${i}`,
            'owner00',
            i,
            'paragraph',
            '[]',
            'ordinary text',
            'Heading',
            'Path',
            'shared',
          ],
        });
      await f.db.execute('COMMIT');
      await ensureSectionsSchema(f.db, 2);
      const capped = await searchSections(f.db, 'zeta', simple, 5);
      expect(capped).toHaveLength(1);
      expect(capped[0].diagnostics.semanticCapped).toBe(true);
    } finally {
      await f.db.close();
    }
  });
  // @lat: [[tests/search#Hybrid Retrieval#Keeps readers alive across process boundaries]]
  it('waits for a cross-process reader before publishing search.db', async () => {
    const f = fixture('# Guide\n\nneedle original');
    const build = (db: SearchDb) =>
      ensureSectionsSchema(db, 2).then(() => indexSections(f.lat, db, simple));
    await writeIndex(f.lat, undefined, false, build);
    const child = fork(
      join(import.meta.dirname, 'support', 'search-reader.mjs'),
      [join(f.lat, '.cache', INDEX_FILE)],
      { execArgv: [], silent: true },
    );
    let stderr = '';
    child.stderr!.on('data', (data) => {
      stderr += data;
    });
    try {
      const failed = once(child, 'exit').then(([code]) => {
        if (code !== 0) throw new Error(stderr || `reader exited ${code}`);
        return [];
      });
      expect((await Promise.race([once(child, 'message'), failed]))[0]).toBe(
        'ready',
      );
      writeFileSync(join(f.lat, 'guide.md'), '# Guide\n\nneedle replacement');
      let built!: () => void;
      const stagingBuilt = new Promise<void>((resolve) => {
        built = resolve;
      });
      let published = false;
      const publication = writeIndex(f.lat, undefined, true, async (db) => {
        await build(db);
        built();
      }).then(() => {
        published = true;
      });
      await stagingBuilt;
      expect(published).toBe(false);
      const closed = new Promise<void>((resolve) =>
        child.on('message', (message) => {
          if (message === 'closed') resolve();
        }),
      );
      const response = once(child, 'message');
      child.send('read');
      const [rows] = await Promise.race([response, failed]);
      expect(rows).toEqual([
        expect.objectContaining({
          body: 'needl origin',
          score: expect.any(Number),
        }),
      ]);
      await closed;
      await publication;
      const replacement = openDb(f.lat, undefined, true);
      try {
        expect(
          (await searchSections(replacement, 'needle', simple))[0].evidence[0]
            .text,
        ).toBe('needle replacement');
        expect(
          readdirSync(join(f.lat, '.cache')).filter(
            (name) => name !== 'parsed' && !name.endsWith('-wal'),
          ),
        ).toEqual([
          'search-access-gate.lock',
          'search-access.lock',
          'search-write.lock',
          INDEX_FILE,
        ]);
      } finally {
        await replacement.close();
      }
      child.send('exit');
      if (child.exitCode === null) await once(child, 'exit');
    } finally {
      child.kill();
    }
  });
  // @lat: [[tests/search#Hybrid Retrieval#Embeds outside database access]]
  it('allows publication while embedding and waits for active queries on close', async () => {
    const f = fixture('# Guide\n\nneedle');
    await writeIndex(f.lat, undefined, true, async (db) => {
      await ensureSectionsSchema(db, 2);
      await indexSections(f.lat, db, simple);
      await setStoredModel(db, 'local:test:2');
    });
    let start!: () => void, finish!: () => void;
    const started = new Promise<void>((resolve) => {
      start = resolve;
    });
    const finishing = new Promise<void>((resolve) => {
      finish = resolve;
    });
    const session = await openIndexedSearchSession(f.lat, {
      createSearchEngine: async () => ({
        ...simple,
        embed: async (texts) => {
          start();
          await finishing;
          return simple.embed(texts);
        },
      }),
    });
    const pending = session.search('needle', 5);
    await started;
    const release = await acquireSearchAccess(
      join(f.lat, '.cache'),
      'exclusive',
      0,
    );
    await release();
    let closed = false;
    const closing = session.close().then(() => {
      closed = true;
    });
    expect(closed).toBe(false);
    await expect(session.search('needle', 5)).rejects.toThrow('closed');
    finish();
    expect(await pending).toHaveLength(1);
    await closing;
    expect(closed).toBe(true);
  });
  // @lat: [[tests/search#Hybrid Retrieval#Rebuilds an unreadable published database]]
  it('replaces an unreadable database during a fresh rebuild', async () => {
    const f = fixture('# Guide\n\nneedle');
    const cache = join(f.lat, '.cache');
    mkdirSync(cache);
    writeFileSync(join(cache, INDEX_FILE), 'invalid cached database');
    await writeIndex(f.lat, undefined, true, async (db) => {
      await ensureSectionsSchema(db, 2);
      await indexSections(f.lat, db, simple);
    });
    const reader = openDb(f.lat, undefined, true);
    try {
      expect(await searchSections(reader, 'needle', simple)).toHaveLength(1);
    } finally {
      await reader.close();
    }
  });
});

import { LEXICAL_VERSION } from '../src/search/lexical.js';
vi.mock('node:fs', () => ({ existsSync: () => true }));
import { beforeEach, describe, expect, it, vi } from 'vitest';
import type { Section } from '@lat.md/core/lattice-model';

const mocks = vi.hoisted(() => ({
  hasIndex: vi.fn(),
  closeDb: vi.fn(),
  embedderForIndex: vi.fn(),
  ensureMeta: vi.fn(),
  ensureSectionsSchema: vi.fn(),
  getStoredModel: vi.fn(),
  openDb: vi.fn(),
  searchSections: vi.fn(),
}));

vi.mock('../src/search/db.js', () => ({
  hasIndex: mocks.hasIndex,
  closeDb: mocks.closeDb,
  ensureMeta: mocks.ensureMeta,
  ensureSectionsSchema: mocks.ensureSectionsSchema,
  getStoredModel: mocks.getStoredModel,
  openDb: mocks.openDb,
}));

vi.mock('../src/search/embedder.js', () => ({
  ReindexRequiredError: class extends Error {},
  embedderForIndex: mocks.embedderForIndex,
}));

vi.mock('../src/search/search.js', () => ({
  searchSections: mocks.searchSections,
  prepareSearchQuery: vi.fn().mockResolvedValue([1]),
}));

import {
  openIndexedSearchSession,
  resolveSearchMatches,
} from '../src/search/query.js';

const section: Section = {
  id: 'lat.md/guide#Guide',
  heading: 'Guide',
  depth: 1,
  file: 'lat.md/guide',
  filePath: 'lat.md/guide.md',
  children: [],
  startLine: 1,
  endLine: 3,
  firstParagraph: 'A guide.',
};

describe('indexed search sessions', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mocks.hasIndex.mockReturnValue(true);
    mocks.openDb.mockReturnValue({
      database: 'test',
      execute: vi.fn().mockResolvedValue({
        rows: [
          { key: 'lexical_version', value: LEXICAL_VERSION },
          { key: 'embedding_model', value: 'local:test:1' },
        ],
      }),
    });
    mocks.ensureMeta.mockResolvedValue(undefined);
    mocks.ensureSectionsSchema.mockResolvedValue(undefined);
    mocks.closeDb.mockResolvedValue(undefined);
    mocks.getStoredModel.mockResolvedValue('local:test:1');
    mocks.embedderForIndex.mockResolvedValue({
      name: 'local:test',
      dimensions: 1,
      embed: vi.fn(),
    });
    mocks.searchSections.mockResolvedValue([
      {
        id: section.id,
        file: section.file,
        heading: section.heading,
        content: section.firstParagraph,
        rankScore: 0.8,
      },
      {
        id: 'lat.md/missing#Missing',
        file: 'lat.md/missing',
        heading: 'Missing',
        content: 'Missing from the project snapshot.',
        rankScore: 0.7,
      },
    ]);
  });

  // @lat: [[tests/search#RAG Tests#Reuses an indexed search session]]
  it('reuses the embedder and closes database access between queries', async () => {
    const createSearchEngine = vi.fn();
    const session = await openIndexedSearchSession('/project/lat.md', {
      cacheDir: '/runtime/cache',
      createSearchEngine,
    });

    const results = await session.search('first', 7, 0.4);
    expect(results).toEqual([
      {
        id: section.id,
        file: section.file,
        heading: section.heading,
        content: section.firstParagraph,
        rankScore: 0.8,
      },
      {
        id: 'lat.md/missing#Missing',
        file: 'lat.md/missing',
        heading: 'Missing',
        content: 'Missing from the project snapshot.',
        rankScore: 0.7,
      },
    ]);
    expect(
      resolveSearchMatches(
        results,
        new Map([[section.id.toLowerCase(), section]]),
      ),
    ).toEqual([{ section, reason: 'hybrid match', rankScore: 0.8 }]);
    await session.search('second', 3);
    await session.close();
    await session.close();

    expect(mocks.openDb).toHaveBeenCalledTimes(3);
    expect(mocks.openDb).toHaveBeenCalledWith(
      '/project/lat.md',
      '/runtime/cache',
      true,
    );
    expect(mocks.embedderForIndex).toHaveBeenCalledOnce();
    expect(mocks.embedderForIndex).toHaveBeenCalledWith(
      'local:test:1',
      '/project/lat.md',
      createSearchEngine,
    );
    expect(mocks.ensureSectionsSchema).not.toHaveBeenCalled();
    expect(mocks.ensureMeta).not.toHaveBeenCalled();
    expect(mocks.searchSections).toHaveBeenNthCalledWith(
      1,
      expect.anything(),
      'first',
      expect.anything(),
      7,
      0.4,
      [1],
    );
    expect(mocks.searchSections).toHaveBeenNthCalledWith(
      2,
      expect.anything(),
      'second',
      expect.anything(),
      3,
      undefined,
      [1],
    );
    expect(mocks.closeDb).toHaveBeenCalledTimes(3);
  });

  // @lat: [[tests/search#RAG Tests#Skips an unbuilt search index]]
  it('returns no matches without loading an embedder for an unbuilt index', async () => {
    mocks.openDb.mockReturnValue({
      execute: vi.fn().mockResolvedValue({ rows: [] }),
    });
    const session = await openIndexedSearchSession('/project/lat.md');

    await expect(session.search('query', 5)).resolves.toEqual([]);
    await session.close();

    expect(mocks.embedderForIndex).not.toHaveBeenCalled();
    expect(mocks.ensureSectionsSchema).not.toHaveBeenCalled();
    expect(mocks.searchSections).not.toHaveBeenCalled();
    expect(mocks.closeDb).toHaveBeenCalledOnce();
  });
  // @lat: [[tests/search#RAG Tests#Rejects changed session metadata]]
  it('rejects replacement metadata and closes access after failure', async () => {
    const session = await openIndexedSearchSession('/project/lat.md');
    mocks.openDb.mockReturnValue({
      execute: vi.fn().mockResolvedValue({ rows: [] }),
    });
    await expect(session.search('query', 5)).rejects.toThrow(
      'Search index changed',
    );
    expect(mocks.searchSections).not.toHaveBeenCalled();
    expect(mocks.closeDb).toHaveBeenCalledTimes(2);
    await session.close();
    await expect(session.search('query', 5)).rejects.toThrow('closed');
  });
});

