    'Appendix\n========\n\nThis file exists upstream but is not referenced by the Lat project.\n',
  );
  writeFileSync(
    join(checkout, 'docs', 'appendix.adoc'),
    '= Appendix\n\nThis file exists upstream but is not referenced by the Lat project.\n',
